	"os"
	"strconv"
)

// isPrime checks if a number is prime
func isPrime(n int) bool {
	if n < 2 {
		return false
	}
	if n == 2 {
		return true
	}
	if n%2 == 0 {
		return false
	}
	for i := 3; i*i <= n; i += 2 {
		if n%i == 0 {
			return false
		}
	}
	return true
}

func main() {
	// Check if exactly one argument is provided
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "Usage: program <N>")
