	// Parse the integer argument
	n, err := strconv.Atoi(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, "Error: Invalid integer argument")
		os.Exit(1)
	}

	// If N < 2, there are no primes up to N
	if n < 2 {
		return
	}

	// Print all primes up to and including N
	for i := 2; i <= n; i++ {
		if isPrime(i) {
			fmt.Println(i)
		}
	}
}
